# Homelander (j_* bones): which model bone the game drives - map <model bone> <game bone> [<bone the direction is taken to>]
# (the overlay's own default; this file is the example for other models - assets/robrun_skin_<name>.map)
pelvis j_mainroot
map j_mainroot M_spine_1_jnt
map j_spinelower M_spine_1_jnt j_spineupper
map j_spineupper M_spine_2_jnt j_spine4
map j_spine4 M_spine_3_jnt j_neck
map j_neck M_neck_jnt j_head
map j_head M_head_1_jnt
