map j_ball_ri R_foot_1_jnt
map j_index_le_1 L_index_1_jnt j_index_le_2
map j_index_le_2 L_index_2_jnt j_index_le_3
map j_index_le_3 L_index_3_jnt
map j_mid_le_1 L_middle_1_jnt j_mid_le_2
map j_mid_le_2 L_middle_2_jnt j_mid_le_3
map j_mid_le_3 L_middle_3_jnt
map j_ring_le_1 L_ring_1_jnt j_ring_le_2
map j_ring_le_2 L_ring_2_jnt j_ring_le_3
map j_ring_le_3 L_ring_3_jnt
